"""Original pulmonary vascular chapter: acute PE."""
from qbank_authoring import question,ref,finalize
PE=ref('AHA/ACC Multisociety: Acute Pulmonary Embolism Guideline, 2026','https://www.jacc.org/doi/10.1016/j.jacc.2025.11.005')
PH=ref('ESC/ERS: Diagnosis and Treatment of Pulmonary Hypertension, 2022','https://academic.oup.com/eurheartj/article/43/38/3618/6673929')
rows=[]
def q(*a,**k):rows.append(question(*a,**k))
q('What is the appropriate role of D-dimer in a hemodynamically stable adult with suspected acute PE?', 'A validated rule-out strategy in an appropriate low or intermediate pretest-probability population',[
 ('A positive result independently confirms PE','D-dimer is nonspecific and can rise in many conditions.'),('A negative result should overrule high clinical probability in every patient','High probability generally requires imaging rather than relying on D-dimer alone.'),('It measures the anatomical size of an embolus','The value does not directly define clot location or burden.')],
 'Pretest probability determines the meaning of the test', '**D-dimer is most useful for exclusion in a validated diagnostic pathway.**',['A sensitive assay and appropriate cutoff are essential.','Age-adjusted or probability-adjusted approaches must be applied as validated.'], '**Use imaging when the pathway indicates it.**',['A positive result is a reason for further assessment, not automatic anticoagulation for proven PE.','Do not apply a rule indiscriminately to populations in which it has not been validated.'],[['Low/intermediate probability','D-dimer may rule out'],['Positive D-dimer','Not diagnostic'],['High probability','Imaging-based assessment']],[PE])
q('For a 70-year-old in an appropriate age-adjusted D-dimer pathway using a standard cutoff of 500 ng/mL FEU, what is the age-adjusted threshold?', '700 ng/mL FEU',[
 ('70 ng/mL FEU','This omits the factor of ten.'),('5,000 ng/mL FEU','This is not the age-adjusted calculation.'),('700 ng/mL regardless of assay units or calibration','FEU and DDU reporting are not interchangeable.')],
 'Units are part of the diagnostic rule', '**For patients over 50, age times ten gives the commonly used FEU threshold in ng/mL.**',['At age 70, this is 700.','The rule belongs within an appropriate clinical-probability strategy.'], '**Check the laboratory method.**',['Do not transfer the number unchanged to a DDU assay.','A high-probability or unstable presentation needs a different diagnostic approach.'],[['Age','70 years'],['Calculation','70 × 10'],['Threshold','700 ng/mL FEU in the stated pathway']],[PE])
q('A patient has a high clinical probability of PE and is stable enough for definitive imaging. Which approach is most appropriate?', 'Proceed to appropriate pulmonary vascular imaging rather than using D-dimer as the decisive rule-out test',[
 ('Exclude PE solely because the D-dimer is below a low-risk threshold','The high pretest probability changes test interpretation.'),('Use a normal chest radiograph to rule out PE','A chest radiograph cannot exclude embolism.'),('Use sinus tachycardia as definitive proof','It is neither sufficiently sensitive nor specific.')],
 'Choose the diagnostic step that matches the probability', '**CT pulmonary angiography is a common definitive test when suitable.**',['V/Q imaging can be appropriate when CTPA is unsuitable.','Contrast, renal function, pregnancy and local expertise influence selection.'], '**Assess urgency and treatment while arranging imaging.**',['Do not ignore bleeding risk when considering empiric anticoagulation.','A discordant result may need further evaluation.'],[['High probability','Proceed to imaging'],['Normal radiograph','Does not exclude PE'],['Alternative test','V/Q in suitable circumstances']],[PE],style='clinical_scenario')
q('Which finding is the most important determinant of immediate high-risk physiology in acute PE?', 'Persistent hypotension or shock attributable to the embolism',[
 ('A saddle location alone with stable circulation','Anatomical appearance alone does not establish cardiopulmonary failure.'),('An isolated elevated D-dimer','This is not a severity classification.'),('Pleuritic pain alone','Pain does not define hemodynamic risk.')],
 'Risk is driven by cardiopulmonary impact', '**Obstructed pulmonary flow can cause acute RV failure and shock.**',['Clot burden and physiological effect are related imperfectly.','Assess perfusion as well as blood pressure.'], '**Organize urgent multidisciplinary care for impending or established failure.**',['The 2026 AHA/ACC categories integrate severity from A to E.','Reperfusion decisions require both clinical severity and bleeding-risk assessment.'],[['Anatomy','Does not alone define high risk'],['Physiology','Shock and RV failure are central'],['Decision','Severity plus bleeding risk']],[PE])
q('A patient with confirmed PE has persistent shock despite initial support and no major contraindication to thrombolysis. Which strategy should be urgently considered?', 'Reperfusion treatment in addition to anticoagulation',[
 ('Anticoagulation alone with no escalation assessment','Established cardiopulmonary failure requires urgent consideration of advanced therapy.'),('Diuresis as the sole PE-specific treatment','It does not remove the acute vascular obstruction.'),('Delay all treatment until a repeat D-dimer falls','D-dimer trends do not guide this emergency decision.')],
 'Severe PE may need restoration of pulmonary blood flow', '**Systemic thrombolysis is an option when its expected benefit outweighs bleeding risk.**',['Catheter-based treatment or surgical embolectomy may be appropriate alternatives.','Availability, contraindications and expertise affect the choice.'], '**Support the failing RV while definitive treatment is organized.**',['Avoid indiscriminate fluid loading and monitor perfusion.','A PE response team can coordinate urgent decisions.'],[['Failure','Urgent advanced-therapy assessment'],['Options','Thrombolysis, catheter or surgical treatment'],['Selection','Bleeding risk and expertise']],[PE],style='clinical_scenario')
q('A patient with acute PE is normotensive, has a low clinical severity score and no RV dysfunction or myocardial injury. Which initial treatment principle is appropriate?', 'Anticoagulation with assessment for safe outpatient or early-discharge care',[
 ('Routine systemic thrombolysis','Major bleeding risk outweighs benefit in a low-risk presentation.'),('Surgical embolectomy for every segmental clot','This is not indicated solely by that anatomy.'),('No treatment because a normal RV excludes thromboembolism','The PE is confirmed; RV findings inform severity rather than existence.')],
 'Low-risk PE generally needs anticoagulation rather than routine reperfusion', '**Disposition depends on validated risk assessment and practical safety.**',['Check bleeding risk, comorbidity and oxygen needs.','Ensure medication access and reliable follow-up.'], '**Provide return instructions and a duration plan.**',['Early discharge is not absence of care.','Reassess persistent symptoms and treatment complications.'],[['Low-risk physiology','Anticoagulation'],['Disposition','Selected outpatient pathway'],['Avoid','Routine thrombolysis']],[PE],style='clinical_scenario')
q('For most nonpregnant adults with acute PE who are eligible for oral anticoagulation and have no specific contraindication, which class is preferred over vitamin K antagonists in the 2026 guideline?', 'Direct oral anticoagulants',[
 ('Aspirin alone','It is not adequate initial treatment of established PE.'),('Clopidogrel alone','Antiplatelet therapy is not a substitute for therapeutic anticoagulation.'),('Vitamin K antagonists are mandatory for every patient','They are important in selected settings but not universally preferred.')],
 'Choose the anticoagulant for the patient rather than only the diagnosis', '**DOACs are preferred for many eligible adults.**',['Renal function, interactions and absorption affect suitability.','Pregnancy, mechanical valves and selected antiphospholipid syndrome settings require different choices.'], '**Use the correct initiation regimen.**',['Some agents need an initial parenteral phase; others have an oral loading schedule.','Review dose and adherence rather than assuming all DOAC regimens are identical.'],[['Many eligible adults','DOAC preferred'],['Special populations','Different strategy may be needed'],['Initiation','Agent-specific schedule']],[PE])
q('After a first PE provoked by major surgery with the transient factor resolved, which duration principle is most appropriate?', 'A finite primary treatment course, commonly about 3 months, if no other indication for extension exists',[
 ('Stop after 7 days once pain resolves','That is inadequate primary treatment.'),('Lifelong anticoagulation is compulsory for every surgically provoked PE','The resolved major transient factor generally favors a finite course.'),('Continue solely until D-dimer first becomes normal','Duration is not determined by that isolated laboratory endpoint.')],
 'Recurrence risk after the provoking factor matters', '**A major reversible trigger differs from a persistent or unexplained risk.**',['Complete an adequate initial treatment course.','Assess bleeding risk and other continuing indications.'], '**Document the rationale for stopping or extending.**',['The 2026 guideline describes an initial treatment phase of three to six months.','Persistent risk or absence of a major reversible factor often supports extension.'],[['Major resolved trigger','Often finite treatment'],['Persistent risk','May favor extended treatment'],['Decision','Recurrence, bleeding and preferences']],[PE],style='clinical_scenario')
q('What is the main role of an inferior vena cava filter in acute VTE care?', 'Selected situations such as acute PE or proximal DVT with a contraindication to therapeutic anticoagulation',[
 ('Routine addition to effective anticoagulation in every PE','This is not supported as universal care.'),('Dissolution of emboli already in the pulmonary arteries','A filter does not lyse existing pulmonary clot.'),('Replacement of all future anticoagulation indefinitely','Anticoagulation should be reconsidered when safe, and retrieval planned for suitable devices.')],
 'A filter is a mechanical prevention strategy with limitations', '**It may reduce embolization from the lower venous system in selected circumstances.**',['It does not treat the existing clot burden.','Device-associated thrombosis and other complications matter.'], '**Plan reassessment from the time of placement.**',['Resume appropriate anticoagulation when the contraindication resolves.','Retrieve a retrievable filter when no longer needed and feasible.'],[['Selected indication','Anticoagulation contraindication'],['Not a function','Lysis of existing PE'],['Follow-up','Reassess anticoagulation and retrieval']],[PE])
q('Three months after treated PE, a patient remains breathless with exercise limitation. What is the appropriate next principle?', 'Evaluate persistent post-PE symptoms, including possible chronic thromboembolic disease and other cardiopulmonary causes',[
 ('Assume anxiety without assessment','Persistent limitation can reflect treatable disease.'),('Diagnose recurrent acute PE solely from breathlessness','The symptom is not specific.'),('Ignore symptoms once the initial anticoagulation phase ends','Follow-up is part of PE care.')],
 'Recovery after PE deserves an active review', '**Persistent symptoms can reflect CTEPH, residual vascular obstruction, deconditioning or another disease.**',['Review functional recovery and anticoagulation complications.','Use echocardiography and perfusion assessment when indicated.'], '**Refer suspected chronic thromboembolic disease to an expert pathway.**',['A normal initial treatment response does not exclude later impairment.','The work-up should identify the cause rather than relabel every symptom as recurrent PE.'],[['Symptoms persist','Structured reassessment'],['Important cause','Chronic thromboembolic disease'],['Other causes','Cardiac, lung or functional limitations']],[PE,PH],style='clinical_scenario')
q('Which ECG statement is correct in suspected pulmonary embolism?', 'Sinus tachycardia or right-heart strain may occur, but no routine ECG pattern reliably confirms or excludes PE',[
 ('Absence of S1Q3T3 excludes PE','This pattern is neither sensitive nor required.'),('S1Q3T3 is pathognomonic for PE','Other causes of acute right-heart strain can produce it.'),('A normal ECG makes pulmonary vascular imaging unnecessary in a high-probability case','A normal ECG cannot rule out the disease.')],
 'ECG findings are contextual rather than definitive', '**The ECG can reveal strain or competing diagnoses.**',['Right-axis or anterior T-wave abnormalities may support RV stress.','Sinus tachycardia is common but nonspecific.'], '**Use a validated diagnostic pathway.**',['Clinical probability, D-dimer in suitable patients and imaging answer the diagnostic question.','ECG and biomarkers also contribute to severity assessment after confirmation.'],[['ECG','Supportive or alternative-diagnosis information'],['S1Q3T3','Neither sensitive nor specific'],['Diagnosis','Probability-based pathway']],[PE])
q('An unstable patient with possible PE has bedside echocardiographic RV dilatation. Which interpretation is most appropriate?', 'It supports acute RV strain in context but is not independently specific for PE',[
 ('It proves acute PE in every patient','Chronic PH, RV infarction and other conditions can cause RV abnormalities.'),('A normal echocardiogram excludes every PE','Small or non-high-risk PE can have normal RV findings.'),('It directly identifies the full pulmonary arterial clot burden','Echocardiography does not ordinarily map all pulmonary emboli.')],
 'Bedside echocardiography helps assess physiology during instability', '**RV findings can accelerate risk assessment when definitive imaging is difficult.**',['The prior probability and alternative causes remain crucial.','Chronic changes can complicate interpretation.'], '**Integrate bedside findings with urgent diagnostic and treatment decisions.**',['Stabilize first and obtain definitive imaging when feasible.','Do not generalize an emergency bedside algorithm to every stable presentation.'],[['RV dilatation','Strain, not unique to PE'],['Normal RV','Does not exclude all PE'],['Unstable setting','Useful immediate physiological information']],[PE],style='clinical_scenario')
